      if (x.type !== "eq") return '<span class="rc-' + x.type + '">' + esc(x.text) + '</span>';
      var t = x.text;
      if (t.length > 2 * K + 40) t = i === 0 ? "… " + t.slice(-K) : i === parts.length - 1 ? t.slice(0, K) + " …" : t.slice(0, K) + " … " + t.slice(-K);
