    var map = zs.length ? '<div class="cs-map">🗺 ' + esc(PL.onMap) + zs.map(function (z) { return '<button type="button" class="cs-tag" data-plzone="' + esc(z.id) + '">' + esc(z.title || "?") + '</button>'; }).join("") + '</div>' : '';
