    [].forEach.call(document.querySelectorAll("[data-extab]"), function (b) { b.onclick = function () { exTab = b.dataset.extab; exMsg = ""; render(); }; });
    var dd = $("ex-days"); if (dd) dd.onchange = function () { exDays = +dd.value; };
